1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Assigns the owner's {@code customerCode}, formatted {@code <CITY3>-<LAST3>-<NNNN>}
11	 * where CITY3 is the upper-cased first three letters of the city, LAST3 the upper-cased
12	 * first three letters of the last name and NNNN a per-city 4-digit zero-padded sequence
13	 * equal to one more than the owners already in that city (e.g. {@code TOW-SMI-0007}).
14	 * Runs before the owner is saved, so the count reflects the existing owners only.
15	 */
16	public class AssignCustomerCode {
17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
19	        String city = owner.getCity();
20	        String city3 = firstThreeUpper(city);
21	        String last3 = firstThreeUpper(owner.getLastName());
22	        long inCity = ownerRepository.findAll().stream()
23	            .filter(existing -> city.equals(existing.getCity()))
24	            .count();
25	        long sequence = inCity + 1;
26	        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, sequence));
27	    }
28	
29	    private static String firstThreeUpper(String value) {
30	        return value.substring(0, Math.min(3, value.length())).toUpperCase(Locale.ROOT);
31	    }
32	}
